pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    function testFuzz_property(address from, uint256 v, bool includeTos) public {
        vm.assume(from != address(0));

        Reverter reverter = new Reverter();

        address[] memory tos;
        if (includeTos) {
            tos = new address[](1);
            tos[0] = address(0x1234);
        } else {
            tos = new address[](0);
        }

        bool ok;
        try c.transfer(from, address(reverter), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        if (includeTos) {
            assertTrue(ok == false);
        } else {
            assertTrue(ok == false);
        }
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}
